def _backfill_reserved_and_normalize(apps, schema_editor):
    Item = apps.get_model('inventory', 'Item')
    ItemRequest = apps.get_model('inventory', 'ItemRequest')

    Item.objects.filter(available_quantity__gt=F('total_quantity')).update(
        available_quantity=F('total_quantity')
    )
    Item.objects.update(reserved_quantity=0)

    approved_totals = (
        ItemRequest.objects
        .filter(status='approved')
        .values('item_id')
        .annotate(total=Sum('quantity_requested'))
    )
    for row in approved_totals:
        item_id = row['item_id']
        requested_total = row['total'] or 0
        available = (
            Item.objects
            .filter(pk=item_id)
            .values_list('available_quantity', flat=True)
            .first()
        )
        if available is None:
            continue
        Item.objects.filter(pk=item_id).update(
            reserved_quantity=min(requested_total, available)
        )


def _reset_reserved(apps, schema_editor):
    Item = apps.get_model('inventory', 'Item')
    Item.objects.update(reserved_quantity=0)


