def fix_item_encoding(apps, schema_editor):
    Item = apps.get_model('inventory', 'Item')
    Category = apps.get_model('inventory', 'Category')

    replacements = [
        ('Ã¢â‚¬â€', '-'),
        ('Ã¢â€â‚¬', '-'),
        ('Ã¢â‚¬', '-'),
        ('â€”', '-'),
    ]

    for item in Item.objects.all():
        original_name = item.name
        original_desc = item.description
        new_name = original_name
        new_desc = original_desc
        changed = False

        for bad, good in replacements:
            if bad in new_name:
                new_name = new_name.replace(bad, good)
                changed = True
            if bad in new_desc:
                new_desc = new_desc.replace(bad, good)
                changed = True

        if changed:
            item.name = new_name
            item.description = new_desc
            item.save(update_fields=['name', 'description'])

    for category in Category.objects.all():
        original_name = category.name
        original_desc = category.description
        new_name = original_name
        new_desc = original_desc
        changed = False

        for bad, good in replacements:
            if bad in new_name:
                new_name = new_name.replace(bad, good)
                changed = True
            if bad in new_desc:
                new_desc = new_desc.replace(bad, good)
                changed = True

        if changed:
            category.name = new_name
            category.description = new_desc
            category.save(update_fields=['name', 'description'])


